-- On failure: increment attempts and schedule next try or mark FAILED after max attempts
WITH q AS (SELECT attempts FROM message_delivery_queue WHERE id = '{{ $json["queue_id"] }}')
UPDATE message_delivery_queue SET attempts = q.attempts + 1, last_error = '{{ $json["error"] || '' }}', scheduled_at = now() + interval '5 minutes' WHERE id = '{{ $json["queue_id"] }}' AND q.attempts < 5;

-- If attempts >= 5, mark FAILED
UPDATE message_delivery_queue SET status = 'FAILED', last_error = '{{ $json["error"] || '' }}' WHERE id = '{{ $json["queue_id"] }}' AND (SELECT attempts FROM message_delivery_queue WHERE id = '{{ $json["queue_id"] }}') >= 5;
